script:
docname = frappe.form_dict.get("purchase_receipt")

doc = frappe.get_doc("Purchase Receipt", docname)

selling_price_list = frappe.db.get_single_value(
    "Selling Settings",
    "selling_price_list"
) or "Standard Selling"

for item in doc.items:

    if not item.item_code or not item.custom_shelf_price:
        continue

    existing_item_price = frappe.db.get_value(
        "Item Price",
        {
            "item_code": item.item_code,
            "price_list": selling_price_list,
            "selling": 1
        },
        ["name", "price_list_rate"],
        as_dict=True
    )

    if existing_item_price:

        if existing_item_price.price_list_rate != item.custom_shelf_price:

            ip_doc = frappe.get_doc(
                "Item Price",
                existing_item_price.name
            )

            ip_doc.price_list_rate = item.custom_shelf_price
            ip_doc.save(ignore_permissions=True)

    else:

        ip_doc = frappe.get_doc({
            "doctype": "Item Price",
            "item_code": item.item_code,
            "price_list": selling_price_list,
            "selling": 1,
            "currency": frappe.db.get_single_value("Global Defaults", "default_currency"),
            "price_list_rate": item.custom_shelf_price
        })

        ip_doc.insert(ignore_permissions=True)

frappe.response["message"] = "Selling prices updated successfully"
